insert into public.sector_packs(id,version,definition) values ('food-vendor','1.0.0','{"id":"food-vendor","name":"Food vendor","version":"1.0.0","description":"From the morning prep to the evening rush.","uses":["phone-agent","order-taker","stock-monitor","ledger","customer-service","daily-report"],"schemas":{"catalog":"MenuWithIngredients"},"rules":["Use configured menu prices; never invent items or prices.","Combos are only valid when explicitly listed in the menu.","Decrement ingredient quantities only after approval in live mode.","Peak hours: 12:00–14:00 and 18:00–21:00; prioritize stock alerts.","Allergy questions, refunds and unusual orders require owner attention."],"built_by":{"ai_expert":"Gluons reference implementation","sector_expert":"Demo food-operations persona; expert validation pending"},"color":"orange"}'::jsonb) on conflict(id) do update set version=excluded.version,definition=excluded.definition;
insert into public.sector_packs(id,version,definition) values ('retail-shop','1.0.0','{"id":"retail-shop","name":"Retail shop","version":"1.0.0","description":"Keep shelves stocked and customers coming back.","uses":["phone-agent","order-taker","stock-monitor","ledger","customer-service","daily-report"],"schemas":{"catalog":"RetailProductCatalog"},"rules":["Use exact SKU prices from the catalog.","A sale reserves available SKU stock only after human approval.","Returns and refunds require owner attention.","Stock alerts notify the owner; they never purchase inventory automatically."],"built_by":{"ai_expert":"Gluons reference implementation","sector_expert":"Demo retail-operations persona; expert validation pending"},"color":"blue"}'::jsonb) on conflict(id) do update set version=excluded.version,definition=excluded.definition;
insert into public.sector_packs(id,version,definition) values ('field-service','1.0.0','{"id":"field-service","name":"Field services","version":"1.0.0","description":"Trades, cleaning and landscaping administration.","uses":["phone-agent","customer-service","ledger","daily-report","job-intake","job-sheet"],"schemas":{"catalog":"ServiceCatalog"},"rules":["Never diagnose faults or automate physical work. Requested times are unconfirmed. Safety hazards need immediate owner attention.","All actions require owner approval. Trial actions do not execute.","Catalog prices are configured by the owner; never invent estimates."],"built_by":{"ai_expert":"Gluons reference implementation","sector_expert":"Research-led prototype; practitioner validation pending"},"color":"blue"}'::jsonb) on conflict(id) do update set version=excluded.version,definition=excluded.definition;
insert into public.sector_packs(id,version,definition) values ('property-maintenance','1.0.0','{"id":"property-maintenance","name":"Property maintenance","version":"1.0.0","description":"Capture tenant repair requests and prepare maintenance records.","uses":["phone-agent","customer-service","ledger","daily-report","job-intake","job-sheet"],"schemas":{"catalog":"ServiceCatalog"},"rules":["Never decide tenant eligibility, access rights or legal obligations. No contractor dispatch or access authorization.","All actions require owner approval. Trial actions do not execute.","Catalog prices are configured by the owner; never invent estimates."],"built_by":{"ai_expert":"Gluons reference implementation","sector_expert":"Research-led prototype; practitioner validation pending"},"color":"blue"}'::jsonb) on conflict(id) do update set version=excluded.version,definition=excluded.definition;
insert into public.sector_packs(id,version,definition) values ('vehicle-repair','1.0.0','{"id":"vehicle-repair","name":"Vehicle repair","version":"1.0.0","description":"Capture service enquiries, parts counts and work-sheet summaries.","uses":["phone-agent","customer-service","ledger","daily-report","job-intake","job-sheet","stock-monitor"],"schemas":{"catalog":"ServiceCatalog"},"rules":["Never diagnose a vehicle or declare it roadworthy. No repair authorization or parts purchase without owner approval.","All actions require owner approval. Trial actions do not execute.","Catalog prices are configured by the owner; never invent estimates."],"built_by":{"ai_expert":"Gluons reference implementation","sector_expert":"Research-led prototype; practitioner validation pending"},"color":"blue"}'::jsonb) on conflict(id) do update set version=excluded.version,definition=excluded.definition;
